/* ─── src/features/skills/pages/SkillsPage.tsx ──────────────── */
import React, { useEffect, useMemo, useState } from 'react';
import {
  createCategory, createSkill,
  deleteCategory, deleteSkill,
  fetchCategories, fetchSkills,
  updateCategory, updateSkill,
} from '../api/skillsService';
import { JobCategory, Skill } from '../types';

/* ── design tokens ──────────────────────────────────────────── */
const ORANGE = '#EA580C';
const NAVY   = '#0F172A';
const SLATE  = '#64748B';
const BORDER = '#E2E8F0';
const BG     = '#F8FAFC';
const RED    = '#DC2626';
const GREEN  = '#16A34A';

/* ── tiny helpers ───────────────────────────────────────────── */
const pill = (bg: string, color: string): React.CSSProperties => ({
  padding: '3px 10px', borderRadius: 20, fontSize: 12,
  fontWeight: 600, background: bg, color,
  display: 'inline-block', whiteSpace: 'nowrap',
});

/* ── Modal ──────────────────────────────────────────────────── */
interface ModalProps {
  title: string;
  onClose: () => void;
  onConfirm: () => void;
  confirmLabel?: string;
  confirmColor?: string;
  loading?: boolean;
  children: React.ReactNode;
}
const Modal: React.FC<ModalProps> = ({
  title, onClose, onConfirm, confirmLabel = 'Save',
  confirmColor = NAVY, loading = false, children,
}) => (
  <>
    <div
      onClick={onClose}
      style={{
        position: 'fixed', inset: 0,
        background: 'rgba(15,23,42,0.35)',
        backdropFilter: 'blur(2px)', zIndex: 200,
        animation: 'fadeIn 0.15s ease',
      }}
    />
    <div style={{
      position: 'fixed', top: '50%', left: '50%',
      transform: 'translate(-50%,-50%)',
      background: '#fff', borderRadius: 16, zIndex: 201,
      width: 'min(460px, 92vw)',
      boxShadow: '0 20px 60px rgba(15,23,42,0.18)',
      fontFamily: "'DM Sans','Helvetica Neue',sans-serif",
      animation: 'popIn 0.2s ease',
    }}>
      {/* header */}
      <div style={{
        padding: '18px 24px', borderBottom: `1px solid ${BORDER}`,
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
      }}>
        <span style={{ fontSize: 15, fontWeight: 700, color: NAVY }}>{title}</span>
        <button onClick={onClose} style={{
          width: 30, height: 30, borderRadius: 8,
          border: `1px solid ${BORDER}`, background: '#fff',
          cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <svg width="13" height="13" viewBox="0 0 14 14" fill="none">
            <path d="M2 2l10 10M12 2L2 12" stroke={SLATE} strokeWidth="1.8" strokeLinecap="round"/>
          </svg>
        </button>
      </div>
      {/* body */}
      <div style={{ padding: '20px 24px' }}>{children}</div>
      {/* footer */}
      <div style={{
        padding: '14px 24px', borderTop: `1px solid ${BORDER}`,
        display: 'flex', gap: 10, justifyContent: 'flex-end',
      }}>
        <button onClick={onClose} style={{
          padding: '9px 20px', borderRadius: 10,
          border: `1px solid ${BORDER}`, background: '#fff',
          fontSize: 14, fontWeight: 600, color: SLATE,
          cursor: 'pointer', fontFamily: 'inherit',
        }}>
          Cancel
        </button>
        <button
          onClick={onConfirm}
          disabled={loading}
          style={{
            padding: '9px 20px', borderRadius: 10,
            border: 'none', background: confirmColor,
            fontSize: 14, fontWeight: 600, color: '#fff',
            cursor: loading ? 'not-allowed' : 'pointer',
            opacity: loading ? 0.7 : 1, fontFamily: 'inherit',
          }}
        >
          {loading ? 'Saving…' : confirmLabel}
        </button>
      </div>
    </div>
    <style>{`
      @keyframes fadeIn { from { opacity:0 } to { opacity:1 } }
      @keyframes popIn  { from { opacity:0; transform:translate(-50%,-48%) scale(0.96) }
                          to   { opacity:1; transform:translate(-50%,-50%) scale(1)    } }
    `}</style>
  </>
);

/* ── ConfirmDelete ───────────────────────────────────────────── */
const ConfirmDelete: React.FC<{
  label: string; onClose: () => void; onConfirm: () => void; loading: boolean;
}> = ({ label, onClose, onConfirm, loading }) => (
  <Modal
    title="Confirm Delete"
    onClose={onClose}
    onConfirm={onConfirm}
    confirmLabel="Delete"
    confirmColor={RED}
    loading={loading}
  >
    <p style={{ margin: 0, fontSize: 14, color: SLATE, lineHeight: 1.6 }}>
      Are you sure you want to delete <strong style={{ color: NAVY }}>{label}</strong>?
      This action cannot be undone.
    </p>
  </Modal>
);

/* ── Input helper ────────────────────────────────────────────── */
const Field: React.FC<{
  label: string; value: string;
  onChange: (v: string) => void;
  placeholder?: string;
}> = ({ label, value, onChange, placeholder }) => (
  <div style={{ marginBottom: 16 }}>
    <label style={{ fontSize: 12, fontWeight: 600, color: SLATE, display: 'block', marginBottom: 6 }}>
      {label}
    </label>
    <input
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      style={{
        width: '100%', boxSizing: 'border-box',
        padding: '10px 14px', borderRadius: 10,
        border: `1px solid ${BORDER}`, fontSize: 14,
        color: NAVY, outline: 'none', fontFamily: 'inherit',
      }}
      onFocus={(e) => (e.currentTarget.style.borderColor = ORANGE)}
      onBlur={(e)  => (e.currentTarget.style.borderColor = BORDER)}
    />
  </div>
);

/* ── Action icon button ──────────────────────────────────────── */
const IconBtn: React.FC<{
  onClick: () => void; title: string; color: string; children: React.ReactNode;
}> = ({ onClick, title, color, children }) => (
  <button
    onClick={onClick}
    title={title}
    style={{
      width: 30, height: 30, borderRadius: 8,
      border: `1px solid ${BORDER}`, background: '#fff',
      cursor: 'pointer', display: 'flex',
      alignItems: 'center', justifyContent: 'center',
      color, transition: 'background 0.1s',
    }}
    onMouseEnter={(e) => (e.currentTarget.style.background = BG)}
    onMouseLeave={(e) => (e.currentTarget.style.background = '#fff')}
  >
    {children}
  </button>
);

/* ══════════════════════════════════════════════════════════════
   MAIN PAGE
══════════════════════════════════════════════════════════════ */
type Tab = 'skills' | 'categories';

type SkillModal =
  | { type: 'create' }
  | { type: 'edit'; skill: Skill }
  | { type: 'delete'; skill: Skill };

type CatModal =
  | { type: 'create' }
  | { type: 'edit'; cat: JobCategory }
  | { type: 'delete'; cat: JobCategory };

const SkillsPage: React.FC = () => {
  const [tab, setTab]               = useState<Tab>('skills');
  const [skills, setSkills]         = useState<Skill[]>([]);
  const [categories, setCategories] = useState<JobCategory[]>([]);
  const [loading, setLoading]       = useState(true);
  const [saving, setSaving]         = useState(false);
  const [search, setSearch]         = useState('');
  const [filterCat, setFilterCat]   = useState<string>('all');

  /* modals */
  const [skillModal, setSkillModal] = useState<SkillModal | null>(null);
  const [catModal, setCatModal]     = useState<CatModal | null>(null);

  /* form state */
  const [formName, setFormName]         = useState('');
  const [formCategoryId, setFormCategoryId] = useState<string>('');

  /* ── load ─────────────────────────────────────────────────── */
  useEffect(() => {
    Promise.all([fetchSkills(), fetchCategories()])
      .then(([s, c]) => { setSkills(s); setCategories(c); })
      .finally(() => setLoading(false));
  }, []);

  /* ── category map ─────────────────────────────────────────── */
  const catMap = useMemo(
    () => new Map(categories.map((c) => [c.id, c.name])),
    [categories],
  );

  /* ── filtered skills ──────────────────────────────────────── */
  const filteredSkills = useMemo(() => {
    const q = search.toLowerCase();
    return skills.filter((s) => {
      const matchSearch = s.name.toLowerCase().includes(q);
      const matchCat    = filterCat === 'all' || s.category_id === filterCat;
      return matchSearch && matchCat;
    });
  }, [skills, search, filterCat]);

  const filteredCats = useMemo(() => {
    const q = search.toLowerCase();
    return categories.filter((c) => c.name.toLowerCase().includes(q));
  }, [categories, search]);

  /* ── open helpers ─────────────────────────────────────────── */
  const openCreateSkill = () => {
    setFormName(''); setFormCategoryId('');
    setSkillModal({ type: 'create' });
  };
  const openEditSkill = (skill: Skill) => {
    setFormName(skill.name);
    setFormCategoryId(skill.category_id ?? '');
    setSkillModal({ type: 'edit', skill });
  };
  const openCreateCat = () => {
    setFormName('');
    setCatModal({ type: 'create' });
  };
  const openEditCat = (cat: JobCategory) => {
    setFormName(cat.name);
    setCatModal({ type: 'edit', cat });
  };

  /* ── skill CRUD ───────────────────────────────────────────── */
  const handleSkillSave = async () => {
    if (!formName.trim()) return;
    setSaving(true);
    const catId = formCategoryId || null;

    if (skillModal?.type === 'create') {
      const created = await createSkill(formName, catId);
      if (created) setSkills((prev) => [...prev, created]);
    } else if (skillModal?.type === 'edit') {
      const ok = await updateSkill(skillModal.skill.id, formName, catId);
      if (ok)
        setSkills((prev) =>
          prev.map((s) =>
            s.id === skillModal.skill.id
              ? { ...s, name: formName.trim(), category_id: catId }
              : s,
          ),
        );
    }
    setSaving(false);
    setSkillModal(null);
  };

  const handleSkillDelete = async () => {
    if (skillModal?.type !== 'delete') return;
    setSaving(true);
    const ok = await deleteSkill(skillModal.skill.id);
    if (ok) setSkills((prev) => prev.filter((s) => s.id !== skillModal.skill.id));
    setSaving(false);
    setSkillModal(null);
  };

  /* ── category CRUD ────────────────────────────────────────── */
  const handleCatSave = async () => {
    if (!formName.trim()) return;
    setSaving(true);

    if (catModal?.type === 'create') {
      const created = await createCategory(formName);
      if (created) setCategories((prev) => [...prev, created]);
    } else if (catModal?.type === 'edit') {
      const ok = await updateCategory(catModal.cat.id, formName);
      if (ok)
        setCategories((prev) =>
          prev.map((c) =>
            c.id === catModal.cat.id ? { ...c, name: formName.trim() } : c,
          ),
        );
    }
    setSaving(false);
    setCatModal(null);
  };

  const handleCatDelete = async () => {
    if (catModal?.type !== 'delete') return;
    setSaving(true);
    const ok = await deleteCategory(catModal.cat.id);
    if (ok) setCategories((prev) => prev.filter((c) => c.id !== catModal.cat.id));
    setSaving(false);
    setCatModal(null);
  };

  /* ── table styles ─────────────────────────────────────────── */
  const th: React.CSSProperties = {
    padding: '11px 16px', textAlign: 'left', fontSize: 12,
    fontWeight: 700, color: SLATE, borderBottom: `1px solid ${BORDER}`,
    background: BG, whiteSpace: 'nowrap',
    textTransform: 'uppercase', letterSpacing: 0.5,
  };
  const td: React.CSSProperties = {
    padding: '13px 16px', fontSize: 14, color: NAVY,
    borderBottom: '1px solid #F1F5F9', verticalAlign: 'middle',
  };

  if (loading)
    return (
      <div style={{ padding: '48px 0', textAlign: 'center', color: SLATE, fontSize: 14, fontFamily: "'DM Sans',sans-serif" }}>
        Loading…
      </div>
    );

  return (
    <div style={{ fontFamily: "'DM Sans','Helvetica Neue',sans-serif", display: 'flex', flexDirection: 'column', gap: 20 }}>

      {/* ── page header ───────────────────────────────────────── */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 22, fontWeight: 800, color: NAVY }}>Skills & Categories</h1>
          <p style={{ margin: '4px 0 0', fontSize: 13, color: SLATE }}>
            Manage skills and job categories used across the platform
          </p>
        </div>
        <button
          onClick={tab === 'skills' ? openCreateSkill : openCreateCat}
          style={{
            padding: '10px 20px', borderRadius: 10, border: 'none',
            background: ORANGE, color: '#fff', fontWeight: 700,
            fontSize: 14, cursor: 'pointer', fontFamily: 'inherit',
            display: 'flex', alignItems: 'center', gap: 7,
          }}
        >
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
            <path d="M7 1v12M1 7h12" stroke="#fff" strokeWidth="2" strokeLinecap="round"/>
          </svg>
          {tab === 'skills' ? 'Add Skill' : 'Add Category'}
        </button>
      </div>

      {/* ── stat chips ────────────────────────────────────────── */}
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
        {[
          { label: 'Total Skills',      value: skills.length,      color: ORANGE },
          { label: 'Categories',        value: categories.length,  color: '#2563EB' },
          { label: 'Uncategorised',     value: skills.filter((s) => !s.category_id).length, color: '#CA8A04' },
        ].map(({ label, value, color }) => (
          <div key={label} style={{
            background: '#fff', border: `1px solid ${BORDER}`, borderRadius: 12,
            padding: '12px 20px', display: 'flex', alignItems: 'center', gap: 12,
          }}>
            <div style={{ width: 8, height: 8, borderRadius: '50%', background: color }} />
            <span style={{ fontSize: 13, color: SLATE, fontWeight: 500 }}>{label}</span>
            <span style={{ fontSize: 20, fontWeight: 800, color: NAVY }}>{value}</span>
          </div>
        ))}
      </div>

      {/* ── tabs + search + filter ─────────────────────────────── */}
      <div style={{
        background: '#fff', border: `1px solid ${BORDER}`,
        borderRadius: 14, overflow: 'hidden',
      }}>
        {/* tab bar */}
        <div style={{ display: 'flex', borderBottom: `1px solid ${BORDER}`, padding: '0 20px' }}>
          {(['skills', 'categories'] as Tab[]).map((t) => (
            <button
              key={t}
              onClick={() => { setTab(t); setSearch(''); setFilterCat('all'); }}
              style={{
                padding: '14px 20px', border: 'none', background: 'none',
                cursor: 'pointer', fontSize: 14, fontFamily: 'inherit',
                fontWeight: tab === t ? 700 : 500,
                color: tab === t ? ORANGE : SLATE,
                borderBottom: tab === t ? `2px solid ${ORANGE}` : '2px solid transparent',
                marginBottom: -1, textTransform: 'capitalize',
                transition: 'all 0.15s',
              }}
            >
              {t === 'skills' ? `Skills (${skills.length})` : `Categories (${categories.length})`}
            </button>
          ))}
        </div>

        {/* toolbar */}
        <div style={{
          padding: '14px 20px', display: 'flex', gap: 10,
          alignItems: 'center', flexWrap: 'wrap',
          borderBottom: `1px solid ${BORDER}`, background: BG,
        }}>
          {/* search */}
          <div style={{ position: 'relative', flex: 1, minWidth: 200 }}>
            <svg style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none' }}
              width="14" height="14" viewBox="0 0 16 16" fill="none">
              <circle cx="7" cy="7" r="5" stroke={SLATE} strokeWidth="1.5"/>
              <path d="M11 11l3 3" stroke={SLATE} strokeWidth="1.5" strokeLinecap="round"/>
            </svg>
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={`Search ${tab}…`}
              style={{
                width: '100%', boxSizing: 'border-box',
                padding: '9px 12px 9px 34px', borderRadius: 10,
                border: `1px solid ${BORDER}`, fontSize: 13,
                color: NAVY, fontFamily: 'inherit', background: '#fff',
                outline: 'none',
              }}
            />
          </div>

          {/* category filter — only shown on skills tab */}
          {tab === 'skills' && (
            <select
              value={filterCat}
              onChange={(e) => setFilterCat(e.target.value)}
              style={{
                padding: '9px 14px', borderRadius: 10,
                border: `1px solid ${BORDER}`, fontSize: 13,
                color: NAVY, fontFamily: 'inherit', background: '#fff',
                cursor: 'pointer', outline: 'none',
              }}
            >
              <option value="all">All Categories</option>
              <option value="">Uncategorised</option>
              {categories.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          )}

          <span style={{ fontSize: 13, color: SLATE, marginLeft: 'auto' }}>
            {tab === 'skills'
              ? `${filteredSkills.length} of ${skills.length}`
              : `${filteredCats.length} of ${categories.length}`}
          </span>
        </div>

        {/* ── SKILLS TABLE ──────────────────────────────────────── */}
        {tab === 'skills' && (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 520 }}>
              <thead>
                <tr>
                  <th style={{ ...th, width: 48, textAlign: 'center' }}>#</th>
                  <th style={th}>Skill Name</th>
                  <th style={th}>Category</th>
                  <th style={{ ...th, textAlign: 'right' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredSkills.length === 0 ? (
                  <tr>
                    <td colSpan={4} style={{ ...td, textAlign: 'center', color: '#94A3B8', padding: '40px 0' }}>
                      {search ? 'No skills match your search.' : 'No skills yet. Add one above.'}
                    </td>
                  </tr>
                ) : (
                  filteredSkills.map((skill, idx) => (
                    <tr
                      key={skill.id}
                      onMouseEnter={(e) => (e.currentTarget.style.background = BG)}
                      onMouseLeave={(e) => (e.currentTarget.style.background = '#fff')}
                      style={{ transition: 'background 0.1s' }}
                    >
                      <td style={{ ...td, textAlign: 'center', color: '#94A3B8', fontSize: 13 }}>
                        {String(idx + 1).padStart(2, '0')}
                      </td>
                      <td style={td}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                          <div style={{
                            width: 32, height: 32, borderRadius: 8,
                            background: '#FFF7ED', display: 'flex',
                            alignItems: 'center', justifyContent: 'center',
                            flexShrink: 0,
                          }}>
                            <svg width="14" height="14" viewBox="0 0 16 16" fill="none">
                              <path d="M3 8h10M8 3l5 5-5 5" stroke={ORANGE} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                          </div>
                          <span style={{ fontWeight: 600, color: NAVY }}>{skill.name}</span>
                        </div>
                      </td>
                      <td style={td}>
                        {skill.category_id && catMap.get(skill.category_id) ? (
                          <span style={pill('#EFF6FF', '#2563EB')}>
                            {catMap.get(skill.category_id)}
                          </span>
                        ) : (
                          <span style={pill('#F1F5F9', '#94A3B8')}>Uncategorised</span>
                        )}
                      </td>
                      <td style={{ ...td, textAlign: 'right' }}>
                        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 6 }}>
                          <IconBtn onClick={() => openEditSkill(skill)} title="Edit" color={SLATE}>
                            <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
                              <path d="M11.5 2.5a2.121 2.121 0 013 3L5 15l-4 1 1-4L11.5 2.5z" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                          </IconBtn>
                          <IconBtn onClick={() => setSkillModal({ type: 'delete', skill })} title="Delete" color={RED}>
                            <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
                              <path d="M2 4h12M5 4V3a1 1 0 011-1h4a1 1 0 011 1v1M6 7v5M10 7v5M3 4l1 9a1 1 0 001 1h6a1 1 0 001-1l1-9" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                          </IconBtn>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        )}

        {/* ── CATEGORIES TABLE ──────────────────────────────────── */}
        {tab === 'categories' && (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 520 }}>
              <thead>
                <tr>
                  <th style={{ ...th, width: 48, textAlign: 'center' }}>#</th>
                  <th style={th}>Category Name</th>
                  <th style={th}>Skills</th>
                  <th style={{ ...th, textAlign: 'right' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredCats.length === 0 ? (
                  <tr>
                    <td colSpan={4} style={{ ...td, textAlign: 'center', color: '#94A3B8', padding: '40px 0' }}>
                      {search ? 'No categories match your search.' : 'No categories yet. Add one above.'}
                    </td>
                  </tr>
                ) : (
                  filteredCats.map((cat, idx) => {
                    const count = skills.filter((s) => s.category_id === cat.id).length;
                    return (
                      <tr
                        key={cat.id}
                        onMouseEnter={(e) => (e.currentTarget.style.background = BG)}
                        onMouseLeave={(e) => (e.currentTarget.style.background = '#fff')}
                        style={{ transition: 'background 0.1s' }}
                      >
                        <td style={{ ...td, textAlign: 'center', color: '#94A3B8', fontSize: 13 }}>
                          {String(idx + 1).padStart(2, '0')}
                        </td>
                        <td style={td}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                            <div style={{
                              width: 32, height: 32, borderRadius: 8,
                              background: '#EFF6FF', display: 'flex',
                              alignItems: 'center', justifyContent: 'center',
                              flexShrink: 0,
                            }}>
                              <svg width="14" height="14" viewBox="0 0 16 16" fill="none">
                                <rect x="2" y="2" width="5" height="5" rx="1" stroke="#2563EB" strokeWidth="1.4"/>
                                <rect x="9" y="2" width="5" height="5" rx="1" stroke="#2563EB" strokeWidth="1.4"/>
                                <rect x="2" y="9" width="5" height="5" rx="1" stroke="#2563EB" strokeWidth="1.4"/>
                                <rect x="9" y="9" width="5" height="5" rx="1" stroke="#2563EB" strokeWidth="1.4"/>
                              </svg>
                            </div>
                            <span style={{ fontWeight: 600, color: NAVY }}>{cat.name}</span>
                          </div>
                        </td>
                        <td style={td}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                            <span style={pill(count > 0 ? '#F0FDF4' : '#F1F5F9', count > 0 ? GREEN : '#94A3B8')}>
                              {count} skill{count !== 1 ? 's' : ''}
                            </span>
                          </div>
                        </td>
                        <td style={{ ...td, textAlign: 'right' }}>
                          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 6 }}>
                            <IconBtn onClick={() => openEditCat(cat)} title="Edit" color={SLATE}>
                              <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
                                <path d="M11.5 2.5a2.121 2.121 0 013 3L5 15l-4 1 1-4L11.5 2.5z" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/>
                              </svg>
                            </IconBtn>
                            <IconBtn onClick={() => setCatModal({ type: 'delete', cat })} title="Delete" color={RED}>
                              <svg width="13" height="13" viewBox="0 0 16 16" fill="none">
                                <path d="M2 4h12M5 4V3a1 1 0 011-1h4a1 1 0 011 1v1M6 7v5M10 7v5M3 4l1 9a1 1 0 001 1h6a1 1 0 001-1l1-9" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/>
                              </svg>
                            </IconBtn>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ══ SKILL MODALS ══════════════════════════════════════════ */}

      {/* create / edit skill */}
      {(skillModal?.type === 'create' || skillModal?.type === 'edit') && (
        <Modal
          title={skillModal.type === 'create' ? 'Add Skill' : 'Edit Skill'}
          onClose={() => setSkillModal(null)}
          onConfirm={handleSkillSave}
          loading={saving}
        >
          <Field
            label="Skill Name"
            value={formName}
            onChange={setFormName}
            placeholder="e.g. React, Plumbing, Graphic Design"
          />
          <div style={{ marginBottom: 4 }}>
            <label style={{ fontSize: 12, fontWeight: 600, color: SLATE, display: 'block', marginBottom: 6 }}>
              Category <span style={{ color: '#94A3B8', fontWeight: 400 }}>(optional)</span>
            </label>
            <select
              value={formCategoryId}
              onChange={(e) => setFormCategoryId(e.target.value)}
              style={{
                width: '100%', padding: '10px 14px', borderRadius: 10,
                border: `1px solid ${BORDER}`, fontSize: 14,
                color: NAVY, fontFamily: 'inherit', background: '#fff',
                outline: 'none', cursor: 'pointer',
              }}
            >
              <option value="">— No category —</option>
              {categories.map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>
        </Modal>
      )}

      {/* delete skill */}
      {skillModal?.type === 'delete' && (
        <ConfirmDelete
          label={skillModal.skill.name}
          onClose={() => setSkillModal(null)}
          onConfirm={handleSkillDelete}
          loading={saving}
        />
      )}

      {/* ══ CATEGORY MODALS ═══════════════════════════════════════ */}

      {/* create / edit category */}
      {(catModal?.type === 'create' || catModal?.type === 'edit') && (
        <Modal
          title={catModal.type === 'create' ? 'Add Category' : 'Edit Category'}
          onClose={() => setCatModal(null)}
          onConfirm={handleCatSave}
          loading={saving}
        >
          <Field
            label="Category Name"
            value={formName}
            onChange={setFormName}
            placeholder="e.g. Technology, Construction, Design"
          />
          {catModal.type === 'edit' && (
            <p style={{ margin: '8px 0 0', fontSize: 12, color: '#94A3B8' }}>
              {skills.filter((s) => s.category_id === catModal.cat.id).length} skill(s) will remain in this category.
            </p>
          )}
        </Modal>
      )}

      {/* delete category */}
      {catModal?.type === 'delete' && (
        <ConfirmDelete
          label={catModal.cat.name}
          onClose={() => setCatModal(null)}
          onConfirm={handleCatDelete}
          loading={saving}
        />
      )}
    </div>
  );
};

export default SkillsPage;
